// Push gate: decides whether the agent may send a push to a user right now.
// Rules (checked in this order, first failure wins):
//   invalid_now / invalid_user_settings  - bad input; fail closed, send nothing
//   quiet_hours                          - local time is inside the user's quiet period
//   daily_cap_reached                    - user already got dailyCap pushes this local calendar day
// "Day" is the calendar day in the user's own time zone (not UTC, not a rolling 24h).
// Quiet period: start inclusive, end exclusive, may wrap past midnight.
// quietStart === quietEnd means no quiet period.
// Only allowed attempts are recorded; blocked ones never count toward the cap.

const KEEP_MS = 3 * 24 * 60 * 60 * 1000; // enough for any time zone change between calls

const formatters = new Map();
function formatterFor(timeZone) {
  let f = formatters.get(timeZone);
  if (!f) {
    f = new Intl.DateTimeFormat('en-US', {
      timeZone,
      hourCycle: 'h23',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
    });
    formatters.set(timeZone, f);
  }
  return f;
}

// Returns { dayKey: "YYYY-MM-DD", minutes: minutes since local midnight }.
function localParts(date, timeZone) {
  const p = {};
  for (const { type, value } of formatterFor(timeZone).formatToParts(date)) p[type] = value;
  return {
    dayKey: `${p.year}-${p.month}-${p.day}`,
    minutes: Number(p.hour) * 60 + Number(p.minute),
  };
}

function parseHHMM(s) {
  if (typeof s !== 'string') return null;
  const m = /^([01]\d|2[0-3]):([0-5]\d)$/.exec(s);
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
}

export function createPushGate() {
  const history = new Map(); // user id -> array of epoch ms of allowed pushes

  function attempt(user, now) {
    const deny = (reason) => ({ allowed: false, reason });

    if (!(now instanceof Date) || Number.isNaN(now.getTime())) return deny('invalid_now');
    if (!user || typeof user !== 'object' || user.id == null || user.id === '') {
      return deny('invalid_user_settings');
    }

    const { id, timeZone, dailyCap } = user;
    const start = parseHHMM(user.quietStart);
    const end = parseHHMM(user.quietEnd);
    if (
      typeof timeZone !== 'string' ||
      start === null ||
      end === null ||
      !Number.isInteger(dailyCap) ||
      dailyCap < 0
    ) {
      return deny('invalid_user_settings');
    }

    let local;
    try {
      local = localParts(now, timeZone);
    } catch {
      return deny('invalid_user_settings'); // unknown IANA zone
    }

    const t = local.minutes;
    let quiet = false;
    if (start < end) quiet = t >= start && t < end;
    else if (start > end) quiet = t >= start || t < end; // wraps past midnight
    if (quiet) return deny('quiet_hours');

    const nowMs = now.getTime();
    const key = String(id);
    const recent = (history.get(key) ?? []).filter((ms) => nowMs - ms < KEEP_MS);
    const sentToday = recent.filter(
      (ms) => localParts(new Date(ms), timeZone).dayKey === local.dayKey,
    ).length;
    if (sentToday >= dailyCap) {
      history.set(key, recent);
      return deny('daily_cap_reached');
    }

    recent.push(nowMs);
    history.set(key, recent);
    return { allowed: true, reason: null };
  }

  return { attempt };
}

import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-sonnet/work/baseline-g2-1/bot.mjs';

const tokyo = { id: 'u1', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
const r = (g, u, iso) => g.attempt(u, new Date(iso));

// Tokyo = UTC+9. 12:00 JST = 03:00Z
let g = createPushGate();
assert.deepEqual(r(g, tokyo, '2026-03-10T03:00:00Z'), { allowed: true, reason: null });
// 23:00 JST (14:00Z) quiet; 06:59 JST (21:59Z) quiet; 07:00 JST (22:00Z) ok
assert.equal(r(g, tokyo, '2026-03-10T14:00:00Z').reason, 'quiet_hours');
assert.equal(r(g, tokyo, '2026-03-10T21:59:00Z').reason, 'quiet_hours');
assert.equal(r(g, tokyo, '2026-03-10T22:00:00Z').allowed, true);
// cap: 2 used so far on Mar 11 JST (07:00). add one more, then blocked
assert.equal(r(g, tokyo, '2026-03-10T23:00:00Z').allowed, true);
assert.equal(r(g, tokyo, '2026-03-11T00:00:00Z').reason, 'daily_cap_reached'); // 3 on Mar 11 JST? 07:00,08:00 -> 2 allowed

import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-sonnet/work/baseline-g2-1/bot.mjs';

const tokyo = { id: 'u1', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
const at = (g, u, iso) => g.attempt(u, new Date(iso));

// Tokyo = UTC+9
let g = createPushGate();
assert.deepEqual(at(g, tokyo, '2026-03-10T03:00:00Z'), { allowed: true, reason: null }); // 12:00 JST
assert.equal(at(g, tokyo, '2026-03-10T14:00:00Z').reason, 'quiet_hours'); // 23:00
assert.equal(at(g, tokyo, '2026-03-10T21:59:00Z').reason, 'quiet_hours'); // 06:59
assert.equal(at(g, tokyo, '2026-03-10T22:00:00Z').allowed, true); // 07:00 Mar 11 (new local day)

// cap uses local day: 3 on Mar 10 JST, 4th blocked, but next local day resets (not UTC midnight)
g = createPushGate();
for (const h of ['00', '01', '02']) assert.equal(at(g, tokyo, `2026-03-10T${h}:00:00Z`).allowed, true); // 09-11 JST Mar 10
assert.equal(at(g, tokyo, '2026-03-10T05:00:00Z').reason, 'daily_cap_reached');
assert.equal(at(g, tokyo, '2026-03-10T15:00:00Z').reason, 'quiet_hours'); // 00:00 Mar 11 JST
assert.equal(at(g, tokyo, '2026-03-10T22:00:00Z').allowed, true); // 07:00 Mar 11 JST: reset
// blocked attempts did not count
assert.equal(at(g, tokyo, '2026-03-10T23:00:00Z').allowed, true);
assert.equal(at(g, tokyo, '2026-03-11T00:00:00Z').allowed, true);
assert.equal(at(g, tokyo, '2026-03-11T01:00:00Z').reason, 'daily_cap_reached');

// users independent; gates independent
assert.equal(at(g, { ...tokyo, id: 'u2' }, '2026-03-11T01:00:00Z').allowed, true);
assert.equal(at(createPushGate(), tokyo, '2026-03-11T01:00:00Z').allowed, true);

// same-day window (13:00-15:00), cap 0, DST (New York spring forward 2026-03-08)
const ny = { id: 'n', timeZone: 'America/New_York', quietStart: '13:00', quietEnd: '15:00', dailyCap: 1 };
g = createPushGate();
assert.equal(at(g, ny, '2026-03-08T17:30:00Z').reason, 'quiet_hours'); // 13:30 EDT
assert.equal(at(g, ny, '2026-03-08T19:00:00Z').allowed, true); // 15:00 EDT
assert.equal(at(g, ny, '2026-03-08T20:00:00Z').reason, 'daily_cap_reached');
assert.equal(at(g, { ...ny, dailyCap: 0, id: 'z' }, '2026-03-08T19:00:00Z').reason, 'daily_cap_reached');
// 22:00-07:00 across DST: 06:30 EDT = 10:30Z quiet
const nyn = { ...ny, id: 'n2', quietStart: '22:00', quietEnd: '07:00' };
assert.equal(at(g, nyn, '2026-03-08T10:30:00Z').reason, 'quiet_hours');
assert.equal(at(g, nyn, '2026-03-08T11:00:00Z').allowed, true); // 07:00 EDT

// bad input fails closed with distinct codes
assert.equal(at(g, { ...tokyo, timeZone: 'Mars/Base' }, '2026-03-10T03:00:00Z').reason, 'invalid_user_settings');
assert.equal(at(g, { ...tokyo, quietStart: '25:00' }, '2026-03-10T03:00:00Z').reason, 'invalid_user_settings');
assert.equal(at(g, tokyo, 'nope').reason, 'invalid_now');
assert.equal(g.attempt(tokyo, new Date('x')).reason, 'invalid_now');
console.log('all ok');
